{
  "schema_version": "1.0.0",
  "batch_id": "C02-OUT1-positive-mixed-artifacts",
  "operation": "add",
  "project_id": "live-trial",
  "domain": "dev-graph",
  "defaults": {
    "owners": ["harness maintainers"],
    "priority": "medium",
    "tracker_binding": "beads",
    "origin_kind": "manual"
  },
  "artifacts": [
    {
      "input_id": "IN-01",
      "title": "tombstone 済みノードが status 検索結果に残り続ける",
      "tags": ["live-trial", "search", "defect"],
      "content": {
        "one_liner": "tombstone 済みノードが run-dev-graph-status の既定検索結果に混入し、担当者が閉じた作業を再着手してしまう。",
        "who_and_when": "dev-graph を日次で参照する実装担当者が、朝の ready 一覧を run-dev-graph-status で引いたときに発生する。",
        "observed_behavior": "status=tombstoned のノード 4 件が既定検索の結果配列に含まれ、count にも計上される。ノードは論理削除済みで file_path の artifact も凍結されている。",
        "expected_behavior": "既定検索は tombstoned を除外し、明示的に status=tombstoned を指定したときだけ返す。count も除外後の件数と一致する。",
        "reproduction": [
          "fixture repository で任意ノードを tombstoned へ遷移させる",
          "run-dev-graph-status を filter 指定なしで実行する",
          "結果配列に tombstoned ノードが含まれ count に加算されていることを確認する"
        ],
        "impact": {
          "scope": "dev-graph を参照する全実装担当者と ready 判定を行う schedule 経路",
          "severity": "high",
          "urgency": "閉じた作業の再着手と lease の無駄取得が発生するため、次の live trial 前に解消したい"
        },
        "scope_in": ["既定検索の status フィルタ既定値", "count 集計の除外条件"],
        "scope_out": ["tombstone 遷移そのものの契約変更", "物理削除の導入"],
        "graph_relations": {
          "resolving_task": "この issue を解消する実装タスク",
          "related_specification": "ノード検索 API の仕様",
          "related_architecture": "検索サービスの backend/security 設計"
        },
        "acceptance": [
          "既定検索の結果配列に status=tombstoned が 0 件になる",
          "status=tombstoned を明示した検索でのみ tombstoned が返る",
          "count が除外後の件数と一致する"
        ],
        "verification": {
          "command": "python3 plugins/dev-graph/scripts/validate-graph-schema.py --graph .dev-graph/state/graph.json",
          "evidence": "eval-log/run-dev-graph-node-receipt.json"
        }
      }
    },
    {
      "input_id": "IN-02",
      "title": "既定検索から tombstoned を除外するフィルタを実装する",
      "tags": ["live-trial", "search", "implementation"],
      "content": {
        "purpose": "既定検索の status フィルタに tombstoned 除外を実装し、閉じたノードの再着手を止める。",
        "background": "tombstone 済みノードが既定検索へ混入する不具合が報告され、検索経路の既定値だけを変更すれば解消できると切り分けられている。",
        "inputs": [
          ".dev-graph/config.json の routing policy",
          "既定検索の filter 既定値を持つ status 経路"
        ],
        "outputs": [
          "既定検索の除外条件と count 集計の修正",
          "tombstoned を明示指定したときの通過経路"
        ],
        "depends_on_input_ids": ["IN-01"],
        "implementation_targets": {
          "frontend": "N/A: UI 変更を伴わない",
          "backend": "検索フィルタの既定値と count 集計",
          "data": "graph state の読み取りのみで書込みは行わない",
          "infrastructure": "N/A: 実行基盤変更なし",
          "security": "secret と絶対 path を成果物へ保存しない",
          "documentation": "運用ハンドブックの検索既定値の記述を更新する"
        },
        "write_scope": {
          "touches": ["specs"],
          "exclusive_resources": ["specs"],
          "parallel_rule": "同一 resource_scope のノードと同時実行しない",
          "branch": "main",
          "lease": "実装前に graph_node_id を claim し heartbeat 60 秒で更新する",
          "completion_projection": "default branch 側の reconciliation だけが done を書く"
        },
        "steps": [
          "既定検索の filter 既定値を特定する",
          "tombstoned 除外条件と count 集計を同一経路で修正する",
          "明示指定時だけ tombstoned を返す分岐を追加する",
          "検証コマンドで graph 整合を確認する"
        ],
        "acceptance": [
          "既定検索が tombstoned を 0 件で返す",
          "明示指定した検索だけが tombstoned を返す",
          "validate-graph-schema.py が exit 0 を返す"
